(java/'ColourPicker.java').write_text('package com.example.evcharge;\nimport android.app.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import android.text.*;import java.util.Locale;\npublic class ColourPicker {\n interface Saved {void save(int colour);}\n static int dp(Context c,int n){return (int)(n*c.getResources().getDisplayMetrics().density+.5f);}\n static class Field extends View {\n float hue,sat,val;Paint p=new Paint(3);Runnable changed;\n Field(Context c,float[] h){super(c);hue=h[0];sat=h[1];val=h[2];setContentDescription("Saturation and brightness colour area");}\n protected void onDraw(Canvas c){int w=getWidth(),h=getHeight();if(w==0||h==0)return;p.setShader(new LinearGradient(0,0,w,0,Color.WHITE,Color.HSVToColor(new float[]{hue,1,1}),Shader.TileMode.CLAMP));c.drawRect(0,0,w,h,p);p.setShader(new LinearGradient(0,0,0,h,Color.TRANSPARENT,Color.BLACK,Shader.TileMode.CLAMP));c.drawRect(0,0,w,h,p);p.setShader(null);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(4);p.setColor(Color.BLACK);float x=Math.max(8,Math.min(w-8,sat*w)),y=Math.max(8,Math.min(h-8,(1-val)*h));c.drawCircle(x,y,12,p);p.setStrokeWidth(2);p.setColor(Color.WHITE);c.drawCircle(x,y,12,p);p.setStyle(Paint.Style.FILL);}\n public boolean onTouchEvent(MotionEvent e){if(e.getAction()==0||e.getAction()==1||e.getAction()==2){getParent().requestDisallowInterceptTouchEvent(true);sat=Math.max(0,Math.min(1,e.getX()/getWidth()));val=1-Math.max(0,Math.min(1,e.getY()/getHeight()));invalidate();if(changed!=null)changed.run();if(e.getAction()==1)performClick();return true;}return super.onTouchEvent(e);}public boolean performClick(){super.performClick();return true;}\n }\n static void show(Activity a,int initial,Saved save){\n float[] hsv=new float[3];Color.colorToHSV(initial,hsv);LinearLayout box=new LinearLayout(a);box.setOrientation(1);box.setPadding(dp(a,20),dp(a,8),dp(a,20),dp(a,12));Field field=new Field(a,hsv);box.addView(field,new LinearLayout.LayoutParams(-1,dp(a,180)));\n View spectrum=new View(a);spectrum.setBackground(new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.LEFT_RIGHT,new int[]{Color.RED,Color.YELLOW,Color.GREEN,Color.CYAN,Color.BLUE,Color.MAGENTA,Color.RED}));LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,dp(a,8));sp.topMargin=dp(a,14);box.addView(spectrum,sp);\n SeekBar hue=new SeekBar(a);hue.setMax(360);hue.setContentDescription("Hue");box.addView(hue);\n TextView sl=new TextView(a);sl.setText("Saturation");box.addView(sl);SeekBar sat=new SeekBar(a);sat.setMax(100);sat.setContentDescription("Saturation");box.addView(sat);\n TextView vl=new TextView(a);vl.setText("Brightness");box.addView(vl);SeekBar val=new SeekBar(a);val.setMax(100);val.setContentDescription("Brightness");box.addView(val);\n View preview=new View(a);box.addView(preview,new LinearLayout.LayoutParams(-1,dp(a,28)));EditText hex=new EditText(a);hex.setSingleLine(true);hex.setHint("#RRGGBB");box.addView(hex);boolean[] changing={false};\n Runnable refresh=()->{int col=Color.HSVToColor(new float[]{field.hue,field.sat,field.val});preview.setBackgroundColor(col);changing[0]=true;hex.setText(String.format(Locale.ROOT,"#%06X",col&0xffffff));hue.setProgress(Math.round(field.hue));sat.setProgress(Math.round(field.sat*100));val.setProgress(Math.round(field.val*100));changing[0]=false;};field.changed=refresh;\n SeekBar.OnSeekBarChangeListener l=new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int n,boolean user){if(!user||changing[0])return;if(b==hue)field.hue=n;else if(b==sat)field.sat=n/100f;else field.val=n/100f;field.invalidate();refresh.run();}};hue.setOnSeekBarChangeListener(l);sat.setOnSeekBarChangeListener(l);val.setOnSeekBarChangeListener(l);\n hex.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int af){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int st,int before,int count){if(changing[0]||!s.toString().matches("#[0-9a-fA-F]{6}"))return;int c=Color.parseColor(s.toString());float[] h=new float[3];Color.colorToHSV(c,h);field.hue=h[0];field.sat=h[1];field.val=h[2];field.invalidate();preview.setBackgroundColor(c);changing[0]=true;hue.setProgress(Math.round(h[0]));sat.setProgress(Math.round(h[1]*100));val.setProgress(Math.round(h[2]*100));changing[0]=false;}});refresh.run();\n ScrollView scroll=new ScrollView(a);scroll.addView(box);AlertDialog d=new AlertDialog.Builder(a).setTitle("Widget background colour").setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{String h=hex.getText().toString().trim();if(!h.matches("#[0-9a-fA-F]{6}")){hex.setError("Use #RRGGBB");return;}save.save(Color.parseColor(h));d.dismiss();}));d.show();\n }\n}\n',encoding="utf-8")

(java/'ChargeWidgetProvider.java').write_text('package com.example.evcharge;\nimport android.appwidget.*;import android.content.*;import android.os.Bundle;import android.view.View;import android.widget.RemoteViews;import android.graphics.*;\npublic class ChargeWidgetProvider extends AppWidgetProvider {\n public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids)update(c,m,id);}public void onAppWidgetOptionsChanged(Context c,AppWidgetManager m,int id,Bundle b){update(c,m,id);}\n static void update(Context c,AppWidgetManager m,int id){android.content.SharedPreferences p=Session.prefs(c);long t=p.getLong("session_target",p.getLong("alarm_target",0));boolean has=t>0;RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget_status);\n int colour=p.getInt("widget_colour",0xff1e293b);Bitmap bitmap=Bitmap.createBitmap(240,120,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);Paint paint=new Paint(3);paint.setColor(colour);canvas.drawRoundRect(0,0,240,120,20,20,paint);v.setImageViewBitmap(R.id.widget_background,bitmap);\n v.setViewVisibility(R.id.widget_background,has?View.VISIBLE:View.GONE);v.setViewVisibility(R.id.widget_content,has?View.VISIBLE:View.GONE);v.setViewVisibility(R.id.widget_icon,has?View.GONE:View.VISIBLE);\n if(has){float goal=p.getFloat("session_target_percent",80);String label=goal==(int)goal?""+(int)goal:""+goal;boolean light=(.2126*Color.red(colour)+.7152*Color.green(colour)+.0722*Color.blue(colour))>155;v.setTextViewText(R.id.widget_heading,label+"% at");v.setTextViewText(R.id.widget_time,Session.time(c,t));boolean alarm=p.getBoolean("alarm_enabled",true)&&p.getLong("alarm_trigger",0)>System.currentTimeMillis()&&Session.exact(c)&&Session.notifications(c)&&Session.channelOn(c);v.setImageViewResource(R.id.widget_bell,alarm?R.drawable.bell_on:R.drawable.bell_off);v.setContentDescription(R.id.widget_bell,alarm?"Alarm scheduled":"No upcoming alarm");v.setInt(R.id.widget_bell,"setColorFilter",light?0xff0f172a:0xffe2e8f0);v.setTextColor(R.id.widget_heading,light?0xff334155:0xffcbd5e1);v.setTextColor(R.id.widget_time,light?0xff086647:0xff4ade80);}\n v.setOnClickPendingIntent(R.id.widget_root,Session.open(c));m.updateAppWidget(id,v);}\n static void refresh(Context c){AppWidgetManager m=AppWidgetManager.getInstance(c);for(int id:m.getAppWidgetIds(new ComponentName(c,ChargeWidgetProvider.class)))update(c,m,id);}\n}\n',encoding="utf-8")
(res/"layout/widget_status.xml").write_text('<FrameLayout xmlns:android="http://schemas.android.com/apk/res/android" android:id="@+id/widget_root" android:layout_width="match_parent" android:layout_height="match_parent">\n<ImageView android:id="@+id/widget_background" android:layout_width="match_parent" android:layout_height="match_parent" android:scaleType="fitXY" android:importantForAccessibility="no"/>\n<ImageView android:id="@+id/widget_icon" android:layout_width="48dp" android:layout_height="48dp" android:layout_gravity="center" android:src="@mipmap/ic_launcher" android:contentDescription="EV 80. Tap to start."/>\n<LinearLayout android:id="@+id/widget_content" android:layout_width="match_parent" android:layout_height="match_parent" android:orientation="horizontal" android:gravity="center_vertical" android:padding="8dp">\n<LinearLayout android:layout_width="0dp" android:layout_weight="1" android:layout_height="wrap_content" android:orientation="vertical">\n<TextView android:id="@+id/widget_heading" android:layout_width="match_parent" android:layout_height="wrap_content" android:textSize="11sp" android:maxLines="1" android:includeFontPadding="false"/>\n<TextView android:id="@+id/widget_time" android:layout_width="match_parent" android:layout_height="wrap_content" android:textSize="24sp" android:maxLines="1" android:textStyle="bold" android:includeFontPadding="false" android:autoSizeTextType="uniform" android:autoSizeMinTextSize="14sp" android:autoSizeMaxTextSize="24sp" android:autoSizeStepGranularity="1sp"/>\n</LinearLayout><ImageView android:id="@+id/widget_bell" android:layout_width="22dp" android:layout_height="22dp" android:layout_marginStart="6dp"/>\n</LinearLayout></FrameLayout>',encoding="utf-8")
